DROP TABLE IF EXISTS `litemall_article`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_article` (
  `id` int NOT NULL AUTO_INCREMENT,
  `category_id` int NOT NULL DEFAULT '0',
  `title` varchar(255) NOT NULL,
  `summary` varchar(511) DEFAULT NULL,
  `pic_url` varchar(255) DEFAULT NULL COMMENT 'cover image',
  `content` mediumtext COMMENT 'sanitized HTML (jsoup custom Safelist, cleaned at write time)',
  `status` varchar(15) NOT NULL DEFAULT 'published' COMMENT 'published|hidden',
  `is_hot` tinyint(1) NOT NULL DEFAULT '0',
  `is_banner` tinyint(1) NOT NULL DEFAULT '0',
  `goods_id` int NOT NULL DEFAULT '0' COMMENT 'related goods, 0 = none',
  `view_count` int NOT NULL DEFAULT '0' COMMENT 'bumped atomically: view_count = view_count + 1',
  `add_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_article_category` (`category_id`,`deleted`),
  KEY `idx_article_customer` (`status`,`deleted`,`add_time`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='article CMS (V36)';
/*!40101 SET character_set_client = @saved_cs_client */;

