--
-- Table structure for table `litemall_brand`
--

DROP TABLE IF EXISTS `litemall_brand`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_brand` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '品牌商名称',
  `desc` varchar(255) NOT NULL DEFAULT '' COMMENT '品牌商简介',
  `pic_url` varchar(255) NOT NULL DEFAULT '' COMMENT '品牌商页的品牌商图片',
  `sort_order` tinyint DEFAULT '50',
  `floor_price` decimal(10,2) DEFAULT '0.00' COMMENT '品牌商的商品低价，仅用于页面展示',
  `add_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint(1) DEFAULT '0' COMMENT '逻辑删除',
  `source` varchar(32) NOT NULL DEFAULT 'manual' COMMENT 'origin of the brand/store row: manual | cj-supplier | future provider names',
  `external_id` varchar(63) DEFAULT NULL COMMENT 'provider-side id (e.g. CJ supplierId); NULL for manual rows',
  `kind` tinyint NOT NULL DEFAULT '0' COMMENT '0 = consumer brand, 1 = supplier store (renders as "Sold by", never "Brand")',
  `display_enabled` tinyint NOT NULL DEFAULT '0' COMMENT 'admin curation gate: 0 = captured but hidden, 1 = publicly rendered',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_brand_source_external` (`source`,`external_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1046006 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='品牌商表';
/*!40101 SET character_set_client = @saved_cs_client */;

