--
-- Table structure for table `litemall_category_margin`
--

DROP TABLE IF EXISTS `litemall_category_margin`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_category_margin` (
  `category_id` int NOT NULL COMMENT 'L1 root category id (litemall_category.pid = 0)',
  `margin` decimal(4,2) NOT NULL COMMENT 'retail = cost x margin for goods under this root; bounds 1.05 - 3.0',
  `add_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='per-L1-category margin override (Wave 14); absent row = global spring.cjdropship.pricing.margin';
/*!40101 SET character_set_client = @saved_cs_client */;

