--
-- Table structure for table `litemall_cj_dispute`
--

DROP TABLE IF EXISTS `litemall_cj_dispute`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_cj_dispute` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_id` int NOT NULL COMMENT 'litemall_order.id (source=cj) this dispute belongs to',
  `user_id` int NOT NULL COMMENT 'owner — every read/write scopes to this',
  `cj_order_id` varchar(64) NOT NULL COMMENT 'CJ order id the dispute was raised against',
  `business_dispute_id` varchar(100) NOT NULL COMMENT 'our idempotency key sent to disputes/create',
  `cj_dispute_id` varchar(100) DEFAULT NULL COMMENT 'CJ dispute id, back-filled from getDisputeList',
  `reason_id` int DEFAULT NULL COMMENT 'CJ disputeReasonId chosen at creation',
  `reason_name` varchar(255) DEFAULT NULL,
  `expect_type` smallint NOT NULL COMMENT '1=refund, 2=reissue (CjDisputeExpectation)',
  `message` varchar(512) NOT NULL DEFAULT '',
  `image_urls` varchar(1024) DEFAULT NULL COMMENT 'comma-separated evidence image URLs',
  `status` varchar(64) DEFAULT NULL COMMENT 'CJ status string as last seen',
  `finally_deal` smallint DEFAULT NULL COMMENT 'CJ resolution: 1=refund, 2=reissue, 3=reject (CjDisputeResolution)',
  `refund_amount` decimal(10,2) DEFAULT NULL COMMENT 'USD amount CJ refunded (informational; customer money-back stays on the local refund flow)',
  `resend_order_code` varchar(100) DEFAULT NULL COMMENT 'CJ reissue order code when finally_deal=2',
  `cancelled` tinyint(1) NOT NULL DEFAULT '0',
  `add_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cj_dispute_business_id` (`business_dispute_id`),
  KEY `idx_cj_dispute_order` (`order_id`),
  KEY `idx_cj_dispute_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='CJ Dropshipping dispute projection per order (V28)';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `litemall_cj_dispute`
--

LOCK TABLES `litemall_cj_dispute` WRITE;
/*!40000 ALTER TABLE `litemall_cj_dispute` DISABLE KEYS */;
/*!40000 ALTER TABLE `litemall_cj_dispute` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `litemall_cj_product`
--

DROP TABLE IF EXISTS `litemall_cj_product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_cj_product` (
  `pid` varchar(64) NOT NULL COMMENT 'CJ raw product id (UUID); used directly for detail fetch + order placement',
  `source` varchar(32) NOT NULL DEFAULT 'cj_dropshipping' COMMENT 'document origin tag',
  `title` varchar(512) NOT NULL DEFAULT '' COMMENT 'English product name (productNameEn)',
  `price` decimal(10,2) DEFAULT NULL COMMENT 'retail price (CJ wholesale x usd-to-cny x margin), local basis',
  `discount_price` decimal(10,2) DEFAULT NULL COMMENT 'discount price (currently unused for CJ)',
  `description` text COMMENT 'cleaned description/remark',
  `image_url` varchar(1024) DEFAULT NULL COMMENT 'productImage URL',
  `brand` varchar(128) DEFAULT NULL COMMENT 'brand (sparse for CJ)',
  `category_names` text COMMENT 'mapped local category names root->leaf (JSON array)',
  `category_ids` varchar(512) DEFAULT NULL COMMENT 'mapped local category ids root->leaf (JSON array)',
  `variants_json` text COMMENT 'per-SKU variant maps (variant_price/stock) as JSON',
  `attributes_json` text COMMENT 'curated attribute name->value pairs as JSON',
  `add_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'soft-delete flag; set when the product disappears upstream',
  `images_json` text COMMENT 'CJ product gallery image URLs (JSON array) for the DB-served detail page',
  `enriched_time` datetime DEFAULT NULL COMMENT 'last detail+inventory enrichment time; NULL = not yet enriched (incremental/resumable)',
  `detail_html` text COMMENT 'full CJ product description (HTML) for the DB-served detail page; brief stays in description',
  `listed_num` int DEFAULT NULL COMMENT 'CJ detail listedNum (merchant listing count)',
  `review_count` int DEFAULT NULL COMMENT 'CJ productComments total',
  `rating` decimal(2,1) DEFAULT NULL COMMENT 'Average CJ review score 0.0-5.0',
  `cj_create_time` datetime DEFAULT NULL COMMENT 'CJ product createTime (true creation date for recency)',
  `reviews_synced_time` datetime DEFAULT NULL COMMENT 'Last CJ review fetch (staleness cursor)',
  `suggest_price` decimal(10,2) DEFAULT NULL COMMENT 'CJ suggestSellPrice lower bound x usdToCny; organic counter_price anchor when above retail',
  `sell_price` decimal(10,2) DEFAULT NULL COMMENT 'raw CJ wholesale price, USD (range lower bound); cost basis for retail = sell_price x margin',
  `supplier_id` varchar(63) DEFAULT NULL COMMENT 'CJ supplierId from product detail; sparse (~half of items)',
  `supplier_name` varchar(255) DEFAULT NULL COMMENT 'raw CJ supplier legal-entity name; never rendered without admin curation',
  `eu_stock_num` int DEFAULT NULL COMMENT 'Units held in EU warehouses at last probe. NULL = never probed (NOT zero).',
  `warehouse_countries` varchar(255) DEFAULT NULL COMMENT 'Distinct warehouse country codes seen at last probe, comma-separated (e.g. "CN,DE"). NULL = never probed.',
  `delisted_strikes` int NOT NULL DEFAULT '0' COMMENT 'Consecutive times CJ explicitly reported no detail for this pid. Reset to 0 on any successful detail fetch. Delisting acts at >= 2.',
  PRIMARY KEY (`pid`),
  KEY `idx_deleted` (`deleted`),
