DROP TABLE IF EXISTS `litemall_cj_sourcing_request`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_cj_sourcing_request` (
  `id` int NOT NULL AUTO_INCREMENT,
  `cj_sourcing_id` varchar(100) DEFAULT NULL COMMENT 'CJ sourcing id from product/sourcing/create; query key for status refresh',
  `cj_pid` varchar(100) DEFAULT NULL COMMENT 'CJ product id the request was created from, when sourced from our catalog',
  `product_name` varchar(200) NOT NULL COMMENT 'sent to CJ (required by their API)',
  `product_image` varchar(500) NOT NULL COMMENT 'sent to CJ (required by their API)',
  `product_url` varchar(500) DEFAULT NULL,
  `remark` varchar(200) DEFAULT NULL,
  `price` decimal(10,2) DEFAULT NULL COMMENT 'target price in USD, optional',
  `source_status` varchar(64) DEFAULT NULL COMMENT 'CJ sourceStatus code as last synced',
  `source_status_str` varchar(200) DEFAULT NULL COMMENT 'CJ human-readable status as last synced',
  `cj_product_id` varchar(100) DEFAULT NULL COMMENT 'CJ product id once sourcing succeeds',
  `cj_variant_sku` varchar(100) DEFAULT NULL COMMENT 'CJ variant sku once sourcing succeeds',
  `add_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cj_sourcing_id` (`cj_sourcing_id`),
  KEY `idx_cj_sourcing_status` (`source_status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='CJ Dropshipping sourcing-request projection (V32)';
/*!40101 SET character_set_client = @saved_cs_client */;

