-- Table structure for table `litemall_comment`
--

DROP TABLE IF EXISTS `litemall_comment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_comment` (
  `id` int NOT NULL AUTO_INCREMENT,
  `value_id` int NOT NULL DEFAULT '0' COMMENT '如果type=0，则是商品评论；如果是type=1，则是专题评论。',
  `type` tinyint NOT NULL DEFAULT '0' COMMENT '评论类型，如果type=0，则是商品评论；如果是type=1，则是专题评论；',
  `content` varchar(1023) DEFAULT '' COMMENT '评论内容',
  `admin_content` varchar(511) DEFAULT '' COMMENT '管理员回复内容',
  `user_id` int NOT NULL DEFAULT '0' COMMENT '用户表的用户ID',
  `has_picture` tinyint(1) DEFAULT '0' COMMENT '是否含有图片',
  `pic_urls` varchar(1023) DEFAULT NULL COMMENT '图片地址列表，采用JSON数组格式',
  `star` smallint DEFAULT '1' COMMENT '评分， 1-5',
  `add_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint(1) DEFAULT '0' COMMENT '逻辑删除',
  `source` varchar(32) NOT NULL DEFAULT 'local' COMMENT 'origin of the review row: local (customer-posted) | cj (ingested CJ productComments)',
  `external_id` varchar(64) DEFAULT NULL COMMENT 'CJ commentId when source=cj (idempotent ingest key)',
  `author_name` varchar(64) DEFAULT NULL COMMENT 'external reviewer display name (masked by CJ) when source=cj; local rows join litemall_user',
  `author_avatar` varchar(255) DEFAULT NULL COMMENT 'external reviewer avatar (CJ country-flag icon URL) when source=cj',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comment_source_external` (`source`,`external_id`),
  KEY `id_value` (`value_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1056 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='评论表';
/*!40101 SET character_set_client = @saved_cs_client */;

