DROP TABLE IF EXISTS `litemall_consent_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_consent_record` (
  `id` int NOT NULL AUTO_INCREMENT,
  `visitor_id` char(36) DEFAULT NULL COMMENT 'NULL for a denial that never had identity minted (by design under strict prior consent)',
  `user_id` int DEFAULT NULL,
  `choice` varchar(8) NOT NULL COMMENT 'granted | denied',
  `scope` varchar(32) NOT NULL DEFAULT 'analytics',
  `occurred_at` datetime(3) DEFAULT NULL COMMENT 'client clock, clamped like events',
  `received_at` datetime(3) NOT NULL,
  `country_code` char(2) DEFAULT NULL COMMENT 'from CF-IPCountry',
  PRIMARY KEY (`id`),
  KEY `idx_consent_visitor` (`visitor_id`,`received_at`),
  KEY `idx_consent_time` (`received_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='server-side lawful-basis audit of consent choices (behavioral targeting Phase 0)';
/*!40101 SET character_set_client = @saved_cs_client */;

