DROP TABLE IF EXISTS `litemall_coupon`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_coupon` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(63) NOT NULL COMMENT '优惠券名称',
  `desc` varchar(127) DEFAULT '' COMMENT '优惠券介绍，通常是显示优惠券使用限制文字',
  `tag` varchar(63) DEFAULT '' COMMENT '优惠券标签，例如新人专用',
  `total` int NOT NULL DEFAULT '0' COMMENT '优惠券数量，如果是0，则是无限量',
  `last_total` int NOT NULL DEFAULT '0' COMMENT '剩余发放数量',
  `is_limited` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否限量',
  `discount` decimal(10,2) DEFAULT '0.00' COMMENT '优惠金额，',
  `discount_type` smallint NOT NULL DEFAULT '0' COMMENT 'Wave 18: 0 = flat amount off (discount = amount), 1 = percent off (discount = rate 1-90)',
  `discount_cap` decimal(10,2) DEFAULT NULL COMMENT 'Wave 18: max absolute discount for percent coupons; NULL = uncapped',
  `min` decimal(10,2) DEFAULT '0.00' COMMENT '最少消费金额才能使用优惠券。',
  `limit` smallint DEFAULT '1' COMMENT '用户领券限制数量，如果是0，则是不限制；默认是1，限领一张.',
  `type` smallint DEFAULT '0' COMMENT '优惠券赠送类型，如果是0则通用券，用户领取；如果是1，则是注册赠券；如果是2，则是优惠券码兑换；',
  `status` smallint DEFAULT '0' COMMENT '优惠券状态，如果是0则是正常可用；如果是1则是过期; 如果是2则是下架。',
  `goods_type` smallint DEFAULT '0' COMMENT '商品限制类型，如果0则全商品，如果是1则是类目限制，如果是2则是商品限制。',
  `goods_value` varchar(1023) DEFAULT '[]' COMMENT '商品限制值，goods_type如果是0则空集合，如果是1则是类目集合，如果是2则是商品集合。',
  `use_type` tinyint NOT NULL DEFAULT '1' COMMENT '使用类型 1全场 2商品 3品类',
  `primary_key` varchar(255) DEFAULT '' COMMENT '关联商品/类目ID串',
  `receive_start_time` datetime DEFAULT NULL COMMENT '可领取开始时间',
  `receive_end_time` datetime DEFAULT NULL COMMENT '可领取结束时间',
  `is_fixed_time` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否固定使用时间段',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `code` varchar(63) DEFAULT NULL COMMENT '优惠券兑换码',
  `time_type` smallint DEFAULT '0' COMMENT '有效时间限制，如果是0，则基于领取时间的有效天数days；如果是1，则start_time和end_time是优惠券有效期；',
  `days` smallint DEFAULT '0' COMMENT '基于领取时间的有效天数days。',
  `start_time` datetime DEFAULT NULL COMMENT '使用券开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '使用券截至时间',
  `add_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint(1) DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='优惠券信息及规则表';
