--
-- Table structure for table `litemall_goods`
--

DROP TABLE IF EXISTS `litemall_goods`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_goods` (
  `id` int NOT NULL AUTO_INCREMENT,
  `goods_sn` varchar(63) NOT NULL DEFAULT '' COMMENT '商品编号',
  `name` varchar(127) NOT NULL DEFAULT '' COMMENT '商品名称',
  `category_id` int DEFAULT '0' COMMENT '商品所属类目ID',
  `brand_id` int DEFAULT '0',
  `gallery` text,
  `keywords` varchar(255) DEFAULT '' COMMENT '商品关键字，采用逗号间隔',
  `brief` varchar(255) DEFAULT '' COMMENT '商品简介',
  `is_on_sale` tinyint(1) DEFAULT '1' COMMENT '是否上架',
  `sort_order` smallint DEFAULT '100',
  `pic_url` varchar(255) DEFAULT NULL COMMENT '商品页面商品图片',
  `share_url` varchar(255) DEFAULT NULL COMMENT '商品分享海报',
  `is_new` tinyint(1) DEFAULT '0' COMMENT '是否新品首发，如果设置则可以在新品首发页面展示',
  `is_hot` tinyint(1) DEFAULT '0' COMMENT '是否人气推荐，如果设置则可以在人气推荐页面展示',
  `unit` varchar(31) DEFAULT '' COMMENT '商品单位，例如件、盒',
  `counter_price` decimal(10,2) DEFAULT '0.00' COMMENT '专柜价格',
  `retail_price` decimal(10,2) DEFAULT '100000.00' COMMENT '零售价格',
  `vip_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'VIP会员价格',
  `cost` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '成本价',
  `give_integral` int NOT NULL DEFAULT '0' COMMENT '购买赠送积分',
  `is_seckill` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否秒杀商品',
  `is_bargain` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否砍价商品',
  `is_benefit` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否优惠商品',
  `is_best` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否精品推荐',
  `is_postage` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否包邮',
  `postage` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '邮费',
  `fictitious` int NOT NULL DEFAULT '0' COMMENT '虚拟销量',
  `browse` int NOT NULL DEFAULT '0' COMMENT '浏览量',
  `bar_code` varchar(15) DEFAULT '' COMMENT '商品条码',
  `video_link` varchar(200) DEFAULT '' COMMENT '主图视频链接',
  `spec_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '规格类型 0单规格 1多规格',
  `temp_id` int NOT NULL DEFAULT '0' COMMENT '运费模板ID',
  `weight` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '重量kg',
  `volume` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '体积m³',
  `version` int NOT NULL DEFAULT '0' COMMENT '并发版本号(乐观锁)',
  `detail` text COMMENT '商品详细介绍，是富文本格式',
  `add_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint(1) DEFAULT '0' COMMENT '逻辑删除',
  `source` varchar(32) NOT NULL DEFAULT 'local' COMMENT 'origin of the goods row: local | cj',
  `cj_pid` varchar(64) DEFAULT NULL COMMENT 'CJ Dropshipping product id (UUID) when source=cj',
  `listed_num` int DEFAULT '0' COMMENT 'CJ platform listing count (popularity); 0 for local',
  `review_count` int DEFAULT '0' COMMENT 'Unified review count (local litemall_comment or CJ productComments)',
  `rating` decimal(2,1) DEFAULT '0.0' COMMENT 'Average review star 0.0-5.0',
  `cj_reviews_ingested_time` datetime DEFAULT NULL COMMENT 'when CJ review bodies were ingested into litemall_comment (demand-driven)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_goods_source_cjpid` (`source`,`cj_pid`),
  KEY `goods_sn` (`goods_sn`),
  KEY `cat_id` (`category_id`),
  KEY `brand_id` (`brand_id`),
  KEY `sort_order` (`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=10010167 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品基本信息表';
