CREATE TABLE `litemall_goods_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `goods_id` int NOT NULL COMMENT '商品ID',
  `admin_id` int DEFAULT '0' COMMENT '操作管理员ID',
  `action` varchar(64) NOT NULL DEFAULT '' COMMENT '操作类型 create/update/on_sale/off_sale/delete',
  `change_detail` varchar(512) DEFAULT '' COMMENT '变更说明',
  `add_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_goods_id` (`goods_id`),
  KEY `idx_admin_id` (`admin_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品操作日志表';
