--
-- Table structure for table `litemall_goods_product`
--

DROP TABLE IF EXISTS `litemall_goods_product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_goods_product` (
  `id` int NOT NULL AUTO_INCREMENT,
  `goods_id` int NOT NULL DEFAULT '0' COMMENT '商品表的商品ID',
  `specifications` varchar(1023) NOT NULL COMMENT '商品规格值列表，采用JSON数组格式',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '商品货品价格',
  `number` int NOT NULL DEFAULT '0' COMMENT '商品货品数量',
  `cost` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '成本价',
  `bar_code` varchar(15) DEFAULT '' COMMENT 'SKU条码',
  `weight` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '重量kg',
  `volume` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '体积m³',
  `url` varchar(125) DEFAULT NULL COMMENT '商品货品图片',
  `add_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint(1) DEFAULT '0' COMMENT '逻辑删除',
  `cj_vid` varchar(64) DEFAULT NULL COMMENT 'CJ Dropshipping variant id (UUID); the key litemall-order replays to CJ createOrder when the parent goods row is source=cj',
  PRIMARY KEY (`id`),
  KEY `goods_id` (`goods_id`),
  KEY `idx_goods_product_cjvid` (`cj_vid`)
) ENGINE=InnoDB AUTO_INCREMENT=15547 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品货品表';
/*!40101 SET character_set_client = @saved_cs_client */;

