INSERT INTO `litemall_mail_outbox` VALUES (1,'wave4@example.com','Your litemall order 20260716374839 is confirmed','Thank you for your purchase!\n\nWe have received your payment for order 20260716374839.\nOrder total: $67.00\n\nWe will let you know as soon as your order ships.\n\n— The litemall team',NULL,'order-confirmation','sent',1,'2026-07-16 13:24:16',NULL,'2026-07-16 13:24:16','2026-07-16 13:24:21',0),(2,'wave4@example.com','Your litemall order 20260716374839 has shipped','Good news — your order 20260716374839 is on its way!\n\nCarrier: PostNord\nTracking number: PN-W6-0001\n\nYou can follow the shipment from the order detail page in your account.\n\n— The litemall team',NULL,'shipped','sent',1,'2026-07-16 13:24:48',NULL,'2026-07-16 13:24:48','2026-07-16 13:24:52',0),(3,'wave4@example.com','Your litemall order 20260716674441 is confirmed','Thank you for your purchase!\n\nWe have received your payment for order 20260716674441.\nOrder total: $59.00\n\nWe will let you know as soon as your order ships.\n\n— The litemall team',NULL,'order-confirmation','sent',1,'2026-07-16 13:26:02',NULL,'2026-07-16 13:26:02','2026-07-16 13:26:07',0),(4,'wave4@example.com','Your pickup code for order 20260716674441','Your order 20260716674441 is paid and ready for in-store pickup.\n\nPickup location: Stockholm Central Store\nPickup code: 3082158855\n\nShow this code at the counter to collect your order.\n\n— The litemall team',NULL,'pickup-code','sent',1,'2026-07-16 13:26:02',NULL,'2026-07-16 13:26:02','2026-07-16 13:26:07',0),(5,'wave4@example.com','Your refund for order 20260716374839 has been approved','Your after-sale request for order 20260716374839 has been approved.\n\nRefund amount: $67.00\n\nThe refund has been issued to your original payment method or account balance.\n\n— The litemall team',NULL,'refund-approved','sent',1,'2026-07-16 13:26:51',NULL,'2026-07-16 13:26:51','2026-07-16 13:26:53',0),(6,'wave4@example.com','Your litemall order 20260716606377 is confirmed','Tha