--
-- Table structure for table `litemall_order`
--

DROP TABLE IF EXISTS `litemall_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_order` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL COMMENT '用户表的用户ID',
  `order_sn` varchar(63) NOT NULL COMMENT '订单编号',
  `order_status` smallint NOT NULL COMMENT '订单状态',
  `aftersale_status` smallint DEFAULT '0' COMMENT '售后状态，0是可申请，1是用户已申请，2是管理员审核通过，3是管理员退款成功，4是管理员审核拒绝，5是用户已取消',
  `consignee` varchar(63) NOT NULL COMMENT '收货人名称',
  `mobile` varchar(63) NOT NULL COMMENT '收货人手机号',
  `address` varchar(255) NOT NULL COMMENT 'Shipping address snapshot: detail, city, province zip, country (legacy rows: unseparated concat)',
  `message` varchar(512) NOT NULL DEFAULT '' COMMENT '用户订单留言',
  `goods_price` decimal(10,2) NOT NULL COMMENT '商品总费用',
  `freight_price` decimal(10,2) NOT NULL COMMENT '配送费用',
  `coupon_price` decimal(10,2) NOT NULL COMMENT '优惠券减免',
  `integral_price` decimal(10,2) NOT NULL COMMENT '用户积分减免',
  `groupon_price` decimal(10,2) NOT NULL COMMENT '团购优惠价减免',
  `deduction_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '钱包抵扣金额',
  `total_num` int NOT NULL DEFAULT '0' COMMENT '订单商品总数',
  `seckill_id` int NOT NULL DEFAULT '0' COMMENT '秒杀活动ID 0=无',
  `bargain_id` int NOT NULL DEFAULT '0' COMMENT '砍价活动ID 0=无',
  `order_price` decimal(10,2) NOT NULL COMMENT '订单费用， = goods_price + freight_price - coupon_price',
  `actual_price` decimal(10,2) NOT NULL COMMENT '实付费用， = order_price - integral_price',
  `pay_id` varchar(63) DEFAULT NULL COMMENT '微信付款编号',
  `pay_time` datetime DEFAULT NULL COMMENT '微信付款时间',
  `ship_sn` varchar(63) DEFAULT NULL COMMENT '发货编号',
  `ship_channel` varchar(63) DEFAULT NULL COMMENT '发货快递公司',
  `ship_time` datetime DEFAULT NULL COMMENT '发货开始时间',
  `refund_amount` decimal(10,2) DEFAULT NULL COMMENT '实际退款金额，（有可能退款金额小于实际支付金额）',
  `refund_type` varchar(63) DEFAULT NULL COMMENT '退款方式',
  `refund_content` varchar(127) DEFAULT NULL COMMENT '退款备注',
  `refund_time` datetime DEFAULT NULL COMMENT '退款时间',
  `confirm_time` datetime DEFAULT NULL COMMENT '用户确认收货时间',
  `comments` smallint DEFAULT '0' COMMENT '待评价订单商品数量',
  `end_time` datetime DEFAULT NULL COMMENT '订单关闭时间',
  `add_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint(1) DEFAULT '0' COMMENT '逻辑删除',
  `address_id` int DEFAULT NULL COMMENT 'litemall_address.id the order was submitted with (structured address for CJ placement)',
  `country_code` varchar(8) DEFAULT NULL COMMENT 'ISO destination country picked at checkout (litemall_address has no country; CJ createOrder needs one)',
  `source` varchar(32) NOT NULL DEFAULT 'local' COMMENT 'fulfillment origin of the order: local | cj',
  `cj_order_id` varchar(64) DEFAULT NULL COMMENT 'CJ Dropshipping order id returned by createOrder when source=cj',
  `cj_order_num` varchar(64) DEFAULT NULL COMMENT 'CJ Dropshipping order number returned by createOrder when source=cj',
  `cj_logistic_name` varchar(64) DEFAULT NULL COMMENT 'CJ logistics line chosen by the customer at checkout (used at placement when still offered)',
  `pink_id` int DEFAULT NULL COMMENT 'combination group-buy slot (litemall_combination_pink.id) this order was placed against; NULL = not a group-buy order',
  `cj_placement_approved_time` datetime DEFAULT NULL COMMENT 'admin approval stamp for CJ placement (Wave 23); NULL = awaiting approval in manual mode',
  `cj_placement_approved_by` varchar(63) DEFAULT NULL COMMENT 'admin (X-User-Id) who approved CJ placement',
  `cj_order_status` varchar(32) DEFAULT NULL COMMENT 'last CJ order status seen by lifecycle sync (source=cj only)',
  `delivery_type` varchar(15) NOT NULL DEFAULT 'express' COMMENT 'express | pickup',
  `store_id` int DEFAULT NULL COMMENT 'pickup store id (delivery_type=pickup)',
  `verify_code` varchar(12) DEFAULT NULL COMMENT 'pickup write-off code, generated at pay time',
  `verify_time` datetime DEFAULT NULL COMMENT 'write-off timestamp',
  `verified_by` varchar(63) DEFAULT NULL COMMENT 'who wrote the order off, e.g. admin:<id>',
  `payment_intent_id` varchar(63) DEFAULT NULL COMMENT 'Stripe PaymentIntent id (pi_...), verified server-side; NULL for wallet/offline tenders',
  `tax_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'Tax collected at checkout (sales tax / VAT); 0.00 when tax is disabled',
  `tax_breakdown` text COMMENT 'Provider tax breakdown JSON (per-jurisdiction lines) for invoices/audit; never summed',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_order_sn` (`order_sn`),
  UNIQUE KEY `uk_order_verify_code` (`verify_code`),
  UNIQUE KEY `uk_order_payment_intent_id` (`payment_intent_id`),
  KEY `idx_order_user_id` (`user_id`),
  KEY `idx_order_pink_id` (`pink_id`)
) ENGINE=InnoDB AUTO_INCREMENT=116 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='订单表';
/*!40101 SET character_set_client = @saved_cs_client */;

