DROP TABLE IF EXISTS `litemall_order_status`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_order_status` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_id` int NOT NULL COMMENT '订单ID',
  `old_status` smallint DEFAULT NULL COMMENT '变更前订单状态码 (LitemallOrderStatus.code); null for the initial create row',
  `new_status` smallint DEFAULT NULL COMMENT '变更后订单状态码 (LitemallOrderStatus.code)',
  `change_type` varchar(32) NOT NULL DEFAULT '' COMMENT '状态变更类型 pay/ship/receive/cancel/refund等',
  `change_message` varchar(255) DEFAULT '' COMMENT '变更说明(可展示给用户)',
  `change_time` datetime NOT NULL COMMENT '变更发生时间',
  `operator` varchar(63) DEFAULT '' COMMENT '操作人 system/admin名/user',
  `add_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_change_type` (`change_type`)
) ENGINE=InnoDB AUTO_INCREMENT=285 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='订单状态变更历史表';
/*!40101 SET character_set_client = @saved_cs_client */;

