--
-- Table structure for table `litemall_page`
--

DROP TABLE IF EXISTS `litemall_page`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_page` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(63) NOT NULL COMMENT 'admin-facing label',
  `position` varchar(15) NOT NULL DEFAULT 'custom' COMMENT 'home|custom',
  `category` varchar(31) NOT NULL DEFAULT 'general' COMMENT 'general|coupon|groupon|season (season = the storefront season strip, Wave 27)',
  `config` mediumtext NOT NULL COMMENT 'palette v1 JSON (<=64KB, app-enforced; see spec-page-palette-v1.md)',
  `status` varchar(15) NOT NULL DEFAULT 'draft' COMMENT 'draft|active',
  `is_template` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'seed-only designed template; read-only via the API — clones are normal pages',
  `add_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  `active_home_slot` varchar(15) GENERATED ALWAYS AS ((case when ((`position` = _utf8mb4'home') and (`status` = _utf8mb4'active') and (`deleted` = 0)) then _utf8mb4'home' else NULL end)) STORED COMMENT 'schema-enforced single active home: UNIQUE ignores NULLs',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_page_active_home` (`active_home_slot`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='DIY pages, palette v1 (V36)';
