/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_product_metric_daily` (
  `goods_id` int NOT NULL,
  `day` date NOT NULL,
  `retail_price` decimal(10,2) DEFAULT NULL,
  `cost` decimal(10,2) DEFAULT NULL COMMENT 'captured CJ wholesale (USD); NULL when not yet captured',
  `margin_pct` decimal(6,2) DEFAULT NULL COMMENT '(retail - cost) / retail * 100; NULL when cost is unknown',
  `stock_total` int DEFAULT NULL COMMENT 'sum of SKU stock at record time',
  `available` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 = pid live at CJ; 0 = vanished from the feed',
  `views` int NOT NULL DEFAULT '0',
  `sales_qty` int NOT NULL DEFAULT '0',
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`goods_id`,`day`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='per-goods daily inventory/margin/engagement series (Wave 12); upsert is idempotent per (goods_id, day)';
