--
-- Table structure for table `litemall_promo_candidate`
--

DROP TABLE IF EXISTS `litemall_promo_candidate`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_promo_candidate` (
  `id` int NOT NULL AUTO_INCREMENT,
  `kind` varchar(16) NOT NULL COMMENT 'coupon | groupon',
  `goods_id` int NOT NULL,
  `day` date NOT NULL COMMENT 'scoring day',
  `tier` varchar(16) NOT NULL COMMENT 'hot | featured | watch',
  `score` decimal(8,2) NOT NULL DEFAULT '0.00',
  `suggestion` varchar(1023) DEFAULT NULL COMMENT 'kind-specific suggested values, JSON object; coupon suggestions are pre-validated against the Wave-18 margin-guard formula',
  `reasons` varchar(1023) DEFAULT NULL COMMENT 'human-readable scoring reasons, JSON array of strings',
  `status` varchar(16) NOT NULL DEFAULT 'proposed' COMMENT 'proposed | dismissed | consumed',
  `ref_id` int DEFAULT NULL COMMENT 'created coupon/combination id, set on consume',
  `add_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
