--
-- Table structure for table `litemall_promotion_campaign`
--

DROP TABLE IF EXISTS `litemall_promotion_campaign`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_promotion_campaign` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '营销活动名称',
  `target_segments` varchar(255) DEFAULT '' COMMENT '目标客户分群(CSV)',
  `min_recency_score` tinyint DEFAULT NULL COMMENT 'R分下限 1-5',
  `min_frequency_score` tinyint DEFAULT NULL COMMENT 'F分下限 1-5',
  `min_monetary_score` tinyint DEFAULT NULL COMMENT 'M分下限 1-5',
  `target_goods_ids` varchar(512) DEFAULT '' COMMENT '目标商品ID(CSV)',
  `linked_promotion_type` varchar(32) DEFAULT NULL COMMENT '关联促销类型 COUPON/SECKILL/BARGAIN/COMBINATION',
  `linked_promotion_id` int DEFAULT NULL COMMENT '关联促销活动ID',
  `start_time` datetime DEFAULT NULL COMMENT '活动开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '活动结束时间',
  `max_audience` int DEFAULT NULL COMMENT '受众人数上限 null不限',
  `max_spend` decimal(10,2) DEFAULT NULL COMMENT '预算上限 null不限',
  `assigned_count` int NOT NULL DEFAULT '0' COMMENT '最近一次评估命中的受众数',
  `spent_budget` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '已消耗预算',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态 0草稿 1进行中 2已完成 3暂停',
  `add_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`),
  KEY `idx_linked_promotion` (`linked_promotion_type`,`linked_promotion_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='营销活动(算法化定向)表';
/*!40101 SET character_set_client = @saved_cs_client */;

