--
-- Table structure for table `litemall_retire_candidate`
--

DROP TABLE IF EXISTS `litemall_retire_candidate`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_retire_candidate` (
  `id` int NOT NULL AUTO_INCREMENT,
  `goods_id` int NOT NULL,
  `day` date NOT NULL COMMENT 'day the proposal was scored',
  `score` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT 'higher = retire sooner',
  `reasons` varchar(1023) DEFAULT NULL COMMENT 'human-readable scoring reasons, JSON array of strings',
  `status` varchar(16) NOT NULL DEFAULT 'proposed' COMMENT 'proposed | approved | dismissed | executed',
  `execute_on` date DEFAULT NULL COMMENT 'scheduled off-sale date for approved rows; executor runs batches with execute_on <= today',
  `add_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_retire_candidate_goods_day` (`goods_id`,`day`),
  KEY `idx_retire_candidate_day_status` (`day`,`status`),
  KEY `idx_retire_candidate_status_execute` (`status`,`execute_on`)
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='scored retirement (off-sale) proposals for weak catalog goods (Wave 14); admin approves/dismisses, executor flips';
/*!40101 SET character_set_client = @saved_cs_client */;

