--

DROP TABLE IF EXISTS `litemall_season_candidate`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_season_candidate` (
  `id` int NOT NULL AUTO_INCREMENT,
  `season_key` varchar(31) NOT NULL,
  `goods_id` int NOT NULL,
  `day` date NOT NULL COMMENT 'scoring day',
  `tier` varchar(16) NOT NULL COMMENT 'hot | featured | watch',
  `score` decimal(8,2) NOT NULL DEFAULT '0.00',
  `reasons` varchar(1023) DEFAULT NULL COMMENT 'human-readable scoring reasons, JSON array of strings',
  `status` varchar(16) NOT NULL DEFAULT 'proposed' COMMENT 'auto = published into the index | proposed = scored but under the tier/cap bar | dismissed = permanent admin veto',
  `config_version_hash` varchar(64) DEFAULT NULL COMMENT 'fingerprint of the rule that scored this row, for grouping',
  `config_snapshot` varchar(1023) DEFAULT NULL COMMENT 'the effective weights used, JSON. Kept BESIDE the hash on purpose: a hash alone resolves to nothing once the rule is edited or deleted.',
  `add_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_season_candidate_season_goods_day` (`season_key`,`goods_id`,`day`),
  KEY `idx_season_candidate_season_day_status` (`season_key`,`day`,`status`),
  KEY `idx_season_candidate_goods` (`goods_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='scored seasonal proposals; status auto rows are what the index publishes as `seasons`';
/*!40101 SET character_set_client = @saved_cs_client */;

