) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='season definitions as data: terms, boosted categories, price band and weights. Adding a season is a row, never a code edit.';
