CREATE TABLE `litemall_seckill` (
  `id` int NOT NULL AUTO_INCREMENT,
  `goods_id` int NOT NULL COMMENT '关联商品ID',
  `goods_name` varchar(127) NOT NULL DEFAULT '' COMMENT '商品名称',
  `pic_url` varchar(255) DEFAULT '' COMMENT '商品图片',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '秒杀价格',
  `cost` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '成本价',
  `stock` int NOT NULL DEFAULT '0' COMMENT '秒杀库存',
  `sales` int NOT NULL DEFAULT '0' COMMENT '已售数量',
  `quota` int NOT NULL DEFAULT '0' COMMENT '限购总数 0不限',
  `quota_show` int NOT NULL DEFAULT '0' COMMENT '页面显示限购数',
  `time` tinyint NOT NULL DEFAULT '0' COMMENT '秒杀时段(小时)',
  `is_postage` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否包邮',
  `postage` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '邮费',
  `temp_id` int NOT NULL DEFAULT '0' COMMENT '运费模板ID',
  `weight` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '重量kg',
  `volume` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '体积m³',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态 0下架 1上架',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  `start_time` datetime DEFAULT NULL COMMENT '秒杀开始时间',
  `stop_time` datetime DEFAULT NULL COMMENT '秒杀结束时间',
  `add_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  `original_retail_price` decimal(10,2) DEFAULT NULL COMMENT 'goods.retail_price captured at swap-on; restored at swap-off',
  `price_swapped` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 while the deal price is live on the goods row',
  `original_sku_prices` text COMMENT 'JSON {productId:{"o":original,"s":swapped}} captured at swap-on; drives per-SKU restore',
  PRIMARY KEY (`id`),
  KEY `idx_goods_id` (`goods_id`),
  KEY `idx_time` (`time`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='秒杀活动商品表';
