  `icon` varchar(255) DEFAULT '' COMMENT '等级图标URL',
  `is_show` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否在前端展示',
  `add_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
