--
-- Table structure for table `litemall_user`
--

DROP TABLE IF EXISTS `litemall_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `litemall_user` (
  `id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(63) NOT NULL COMMENT '用户名称',
  `password` varchar(63) NOT NULL DEFAULT '' COMMENT '用户密码',
  `gender` tinyint NOT NULL DEFAULT '0' COMMENT '性别：0 未知， 1男， 1 女',
  `birthday` date DEFAULT NULL COMMENT '生日',
  `last_login_time` datetime DEFAULT NULL COMMENT '最近一次登录时间',
  `last_login_ip` varchar(63) NOT NULL DEFAULT '' COMMENT '最近一次登录IP地址',
  `user_level` tinyint DEFAULT '0' COMMENT '0 普通用户，1 VIP用户，2 高级VIP用户',
  `nickname` varchar(63) NOT NULL DEFAULT '' COMMENT '用户昵称或网络名称',
  `mobile` varchar(20) NOT NULL DEFAULT '' COMMENT '用户手机号码',
  `email` varchar(127) DEFAULT NULL COMMENT 'Email address (optional, for password reset)',
  `avatar` varchar(255) NOT NULL DEFAULT '' COMMENT '用户头像图片',
  `weixin_openid` varchar(63) NOT NULL DEFAULT '' COMMENT '微信登录openid',
  `session_key` varchar(100) NOT NULL DEFAULT '' COMMENT '微信登录会话KEY',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0 可用, 1 禁用, 2 注销',
  `now_money` decimal(16,2) NOT NULL DEFAULT '0.00' COMMENT '钱包余额',
  `brokerage_price` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '佣金余额',
  `integral` int NOT NULL DEFAULT '0' COMMENT '剩余积分',
  `experience` int NOT NULL DEFAULT '0' COMMENT '剩余经验值',
  `sign_num` int NOT NULL DEFAULT '0' COMMENT '连续签到天数',
  `spread_uid` int NOT NULL DEFAULT '0' COMMENT '推广员ID',
  `spread_time` datetime DEFAULT NULL COMMENT '推广员关联时间',
  `is_promoter` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否推广员',
  `pay_count` int NOT NULL DEFAULT '0' COMMENT '购买次数',
  `spread_count` int NOT NULL DEFAULT '0' COMMENT '下级人数',
  `card_id` varchar(20) DEFAULT '' COMMENT '身份证号',
  `group_id` varchar(127) DEFAULT '' COMMENT '用户分组ID',
  `tag_id` varchar(127) DEFAULT '' COMMENT '标签ID',
  `login_type` varchar(36) DEFAULT '' COMMENT '登录类型 h5/wechat/routine',
  `path` varchar(255) DEFAULT '/0/' COMMENT '推广等级链路',
  `subscribe` tinyint(1) DEFAULT '0' COMMENT '是否关注公众号',
  `subscribe_time` datetime DEFAULT NULL COMMENT '关注公众号时间',
  `country` varchar(20) DEFAULT 'CN' COMMENT '国家代码',
  `add_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint(1) DEFAULT '0' COMMENT '逻辑删除',
  `is_guest` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Wave 16: shadow account auto-provisioned at guest checkout; cleared on claim',
  `google_sub` varchar(64) DEFAULT NULL COMMENT 'Wave 16: Google ID-token subject for Sign in with Google account linking',
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_name` (`username`),
  UNIQUE KEY `uk_litemall_user_google_sub` (`google_sub`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户表';
/*!40101 SET character_set_client = @saved_cs_client */;

